use std::{fs,path::Path};use serde_json::json;fn main(){let root=Path::new("/home/ubuntu/src/zopro-perf-work/fq6-toom175");let d=Path::new("/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-29-fq6-toom175");let p=d.join("README.md");let s=fs::read_to_string(&p).unwrap();let before="|Profile|Samples|\n";let after="The short chain recordings contain only 59 samples each; final-exponentiation recordings contain 134 each. They support coarse inspection only and are not resampled or treated as fine-grained cost attribution.\n\n|Profile|Samples|\n";assert_eq!(s.matches(before).count(),1);fs::write(p,s.replace(before,after)).unwrap();fs::copy(root.join("publication.rs"),d.join("artifacts/publication.rs")).unwrap();fs::write(d.join("artifacts/publication-review.json"),serde_json::to_vec_pretty(&json!({"change":"state retained short-profile sample limits explicitly","before":before,"after":after,"results_gates_counts_unchanged":true,"paper_pdf_verified_sha256":"aac8d7bc0940755c3031b21a742257aa1234344c81da9e4d2bb02e594671355a"})).unwrap()).unwrap();}
